plugins {
    id("typewright.kmp.pure")
}

// Node-economy data packs, generated by data/scripts/build_node_economy_corpus.py and never
// hand-edited, reach this module as resources under typewright/corpus/. The loader is P1's.
val syncCorpusData =
    tasks.register<Sync>("syncCorpusData") {
        description = "Copies data/node-economy-*.json into this module's generated resources."
        from(isolated.rootProject.projectDirectory.dir("data")) {
            include("node-economy-*.json")
            into("typewright/corpus")
        }
        into(layout.buildDirectory.dir("generated/corpusData"))
    }

kotlin {
    sourceSets {
        commonMain {
            dependencies {
                api(project(":core-geometry"))
            }
            resources.srcDir(syncCorpusData)
        }
    }
}
